import { NextResponse } from 'next/server';
import { getUserFromRequest } from '@/lib/services/auth';
import { getAssetUrl } from '@/lib/storage/storageService';
import { getUserAssetDownload } from '@/lib/services/assets';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

export async function GET(request, { params }) {
  const user = await getUserFromRequest(request);
  if (!user) return NextResponse.json({ error: '请先登录' }, { status: 401 });
  const { id } = await params;
  const asset = await getUserAssetDownload(user.id, id);
  if (!asset || asset.deletedAt) return NextResponse.json({ error: '资产不存在或已删除' }, { status: 404 });
  if (asset.objectKey) {
    const url = await getAssetUrl({
      objectKey: asset.objectKey,
      visibility: asset.visibility || 'private',
      disposition: request.nextUrl.searchParams.get('inline') === '1' ? 'inline' : 'attachment',
      provider: asset.provider,
      locationId: asset.locationId,
      bucket: asset.bucket,
      region: asset.region,
    });
    if (url) {
      const redirectUrl = /^https?:\/\//i.test(url) ? url : new URL(url, request.url);
      return NextResponse.redirect(redirectUrl);
    }
  }
  if (asset.mediaUrl) {
    const redirectUrl = /^https?:\/\//i.test(asset.mediaUrl) ? asset.mediaUrl : new URL(asset.mediaUrl, request.url);
    return NextResponse.redirect(redirectUrl);
  }
  return NextResponse.json({ error: '资产尚未完成存储归档' }, { status: 409 });
}

import { getUserFromRequest, json } from '@/lib/services/auth';
import { updateUserAssetFolder, deleteUserAssetFolder } from '@/lib/services/assets';
import { consumeRateLimit, guardMutation, rateLimitResponse } from '@/lib/security/requestGuard';
import { publicErrorMessage } from '@/lib/security/publicError';

export const runtime = 'nodejs';

export async function PATCH(request, { params }) {
  const user = await getUserFromRequest(request);
  if (!user) return json({ error: '请先登录' }, { status: 401 });

  const guarded = guardMutation(request, { maxBytes: 32 * 1024 });
  if (guarded) return guarded;
  const limit = await consumeRateLimit({ scope: 'asset_folder_update_user', subject: user.id, limit: 120, windowMs: 60 * 60 * 1000 });
  if (!limit.allowed) return rateLimitResponse(limit);

  const { id } = await params;
  if (!id) return json({ error: '缺少文件夹标识' }, { status: 400 });

  try {
    const body = await request.json();
    const updated = await updateUserAssetFolder(user.id, id, {
      name: body.name,
      color: body.color,
      icon: body.icon,
      sortOrder: body.sortOrder !== undefined ? body.sortOrder : (body.sort_order !== undefined ? body.sort_order : undefined),
    });

    return json({ folder: updated });
  } catch (error) {
    console.error('[PATCH /api/assets/folders/[id]]', error);
    const status = error.code === 'FOLDER_NOT_FOUND' ? 404
      : error.code === 'FOLDER_NAME_DUPLICATE' ? 409
        : error.code === 'INVALID_FOLDER_NAME' ? 400
          : 422;
    return json({ error: publicErrorMessage(error, '更新文件夹失败') }, { status });
  }
}

export async function DELETE(request, { params }) {
  const user = await getUserFromRequest(request);
  if (!user) return json({ error: '请先登录' }, { status: 401 });

  const guarded = guardMutation(request, { maxBytes: 8 * 1024 });
  if (guarded) return guarded;
  const limit = await consumeRateLimit({ scope: 'asset_folder_delete_user', subject: user.id, limit: 120, windowMs: 60 * 60 * 1000 });
  if (!limit.allowed) return rateLimitResponse(limit);

  const { id } = await params;
  if (!id) return json({ error: '缺少文件夹标识' }, { status: 400 });

  try {
    const res = await deleteUserAssetFolder(user.id, id);
    return json(res);
  } catch (error) {
    console.error('[DELETE /api/assets/folders/[id]]', error);
    const status = error.code === 'FOLDER_NOT_FOUND' ? 404 : 500;
    return json({ error: publicErrorMessage(error, '删除文件夹失败') }, { status });
  }
}

