import { json } from '@/lib/services/auth';
import { createGenerationQuote } from '@/lib/services/pricingEngine';
import { listActiveModels } from '@/lib/services/models';
import { publicCanvasModel } from '@/lib/canvas/modelDescriptor';
import { getActiveSubscription } from '@/lib/application/dataAccess.js';
import { consumeRateLimit, guardMutation, rateLimitResponse } from '@/lib/security/requestGuard';
import { publicErrorMessage, publicErrorPayload } from '@/lib/security/publicError';
import { generationApiErrorStatus } from '@/lib/security/generationApiErrors';
import { resolveRequestUser } from '@/lib/security/requestUser';
import { readJsonObjectRequestBody } from '@/lib/security/requestJson';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

export async function POST(request) {
  const auth = await resolveRequestUser(request);
  if (!auth.user) return json({ error: auth.error, code: auth.code }, { status: auth.status });
  const { user } = auth;

  try {
    const guarded = guardMutation(request, { maxBytes: 128 * 1024 });
    if (guarded) return guarded;

    const limit = await consumeRateLimit({ scope: 'generation_quote_user', subject: user.id, limit: 60, windowMs: 60 * 60 * 1000 });
    if (!limit.allowed) return rateLimitResponse(limit);

    const parsedBody = await readJsonObjectRequestBody(request);
    if (!parsedBody.ok) {
      const malformedJson = parsedBody.code === 'INVALID_JSON';
      return json({
        error: malformedJson ? '请求内容不是有效 JSON' : '请求 JSON 顶层必须是对象',
        code: parsedBody.code,
      }, { status: 400 });
    }
    const body = parsedBody.value;
    const idempotencyKey = String(request.headers.get('idempotency-key') || '').trim();
    if (idempotencyKey.length < 8 || idempotencyKey.length > 200) {
      return json({ error: '报价请求必须提供有效的 Idempotency-Key', code: 'IDEMPOTENCY_REQUIRED' }, { status: 422 });
    }
    const modelId = body.modelId || body.model || body.endpoint;
    if (!modelId) {
      return json({ error: '必须指定模型 ID' }, { status: 422 });
    }

    // 获取用户当前订阅等级
    const activeSub = await getActiveSubscription(user.id);
    const subscriptionLevel = activeSub?.plan_id || 'free';

    let capability = null;
    if (body.capabilityVersion) {
      const model = (await listActiveModels()).find(model => model.id === modelId);
      if (!model) return json({error:'模型当前不可用',code:'MODEL_NOT_AVAILABLE'},{status:404});
      capability = publicCanvasModel(model,{schemaVersion:2});
      if (capability.capabilityVersion !== body.capabilityVersion) return json({error:'模型能力已更新，请刷新参数并重新报价',code:'MODEL_CAPABILITY_CHANGED'},{status:409});
    }
    const quote = await createGenerationQuote({
      userId: user.id,
      modelId,
      parameters: body.parameters || body,
      ...(capability ? {capabilitySnapshot:{version:capability.capabilityVersion,schema:capability.inputSchema,schemaVersion:2}} : {}),
      subscriptionLevel,
      idempotencyKey,
      requirePublicAvailability: true,
    });

    return json({
      success: true,
      quote_id: quote.quoteId,
      quoteId: quote.quoteId,
      credits: quote.credits,
      creditsQuoted: quote.credits,
      pricing_breakdown: quote.pricingBreakdown,
      pricingBreakdown: quote.pricingBreakdown,
      expires_at: quote.expiresAt,
      expiresAt: quote.expiresAt,
      ttlSeconds: 300,
    }, { status: 201 });
  } catch (error) {
    console.error('[api/generation/quote]', error);
    return json(
      publicErrorPayload(error, '获取模型报价失败', 'QUOTE_FAILED'),
      { status: generationApiErrorStatus(error) },
    );
  }
}

import crypto from 'node:crypto';
import { json } from '@/lib/services/auth';
import { handleGenerationCallback } from '@/lib/services/generationCore';
import { publicErrorMessage } from '@/lib/security/publicError';

export const runtime = 'nodejs';

function isAuthorized(request) {
  const configured = String(process.env.GENERATION_CALLBACK_SECRET || '');
  const received = request.headers.get('x-generation-callback-secret') || '';
  if (configured.length < 32 || received.length !== configured.length) return false;
  return crypto.timingSafeEqual(Buffer.from(received), Buffer.from(configured));
}

export async function POST(request, context) {
  if (!isAuthorized(request)) return json({ error: '无效的供应商回调凭据' }, { status: 401 });
  const callbackKey = request.headers.get('idempotency-key') || request.headers.get('x-idempotency-key');
  if (!callbackKey || callbackKey.trim().length < 8) return json({ error: '缺少有效的回调幂等键' }, { status: 422 });

  let body;
  try { body = await request.json(); } catch { return json({ error: '无效的回调数据' }, { status: 400 }); }
  const { id } = await context.params;
  try {
    const result = await handleGenerationCallback({
      creationId: id,
      status: body.status,
      resultUrl: body.resultUrl || body.url || null,
      providerRequestId: body.providerRequestId || body.request_id || null,
      errorCode: body.errorCode || body.error_code,
      errorReason: body.errorReason || body.error || undefined,
      actualCostUsd: body.actualCostUsd ?? body.cost_usd ?? null,
      durationMs: body.durationMs ?? null,
      callbackIdempotencyKey: callbackKey,
    });
    if (result.error === 'TASK_NOT_FOUND') return json({ error: '任务不存在' }, { status: 404 });
    return json(result);
  } catch (error) {
    console.error('[api/generations/callback]', error);
    const status = error.code === 'IDEMPOTENCY_REQUIRED' ? 422 : error.code === 'INVALID_CALLBACK_STATUS' ? 400 : 409;
    return json({ error: publicErrorMessage(error, '供应商回调处理失败'), code: error.code || 'CALLBACK_FAILED' }, { status });
  }
}

