  if (!auth.user) return json({ error: auth.error, code: auth.code }, { status: auth.status });
  const { user } = auth;

  try {
    const guarded = guardMutation(request, { maxBytes: 256 * 1024 });
    if (guarded) return guarded;
    const limit = await consumeRateLimit({ scope: 'generation_user', subject: user.id || getClientIp(request), limit: 60, windowMs: 60 * 60 * 1000 });
    if (!limit.allowed) return rateLimitResponse(limit);
    const parsedBody = await readJsonObjectRequestBody(request);
    if (!parsedBody.ok) {
      const malformedJson = parsedBody.code === 'INVALID_JSON';
      return json({
        error: malformedJson ? '请求内容不是有效 JSON' : '请求 JSON 顶层必须是对象',
        code: parsedBody.code,
      }, { status: 400 });
    }
    const body = parsedBody.value;
    const moderation = validatePromptSafety(body.prompt);
    if (!moderation.passed) {
      return json({ error: moderation.reason, code: moderation.code }, { status: 422 });
    }
    const idempotencyKey = request.headers.get('idempotency-key') || request.headers.get('x-idempotency-key');
    const quoteId = String(body.quoteId || body.quote_id || '').trim() || null;
    if (!quoteId) {
      return json({ error: '创建生成任务前必须先获取有效的服务端报价', code: 'QUOTE_REQUIRED' }, { status: 422 });
    }
    const task = await createGenerationTask({
      user,
      modelId: body.modelId || body.model || body.endpoint,
      studioId: body.studioId || 'studio',
      prompt: body.prompt,
      parameters: body.parameters || body,
      quoteParameters: body.parameters || body,
      idempotencyKey,
      label: body.label,
      quoteId,
      expectedCapabilityVersion: body.capabilityVersion || null,
      requirePublicAvailabi

import { NextResponse } from 'next/server';
import { getModelTelemetryOverview } from '@/lib/services/modelTelemetry';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

const RANGES = new Set(['24h', '7d', '30d']);

export async function GET(request) {
  const requested = request.nextUrl.searchParams.get('range') || '24h';
  const timeRange = RANGES.has(requested) ? requested : '24h';

  try {
    const data = await getModelTelemetryOverview({ timeRange, limit: 24 });
    if (data?.error) {
      return NextResponse.json(
        { error: '模型遥测暂不可用' },
        { status: 503, headers: { 'Cache-Control': 'no-store' } }
      );
    }

    const models = (data.topModels || [])
      .filter((item) => item.is_visible !== false)
      .map((item) => ({
        id: item.model_id,
        name: item.model_name,
        category: item.category,
        totalCalls: Number(item.total_calls || 0),
        successRate: Number(item.success_rate || 0),
        avgDurationMs: Number(item.avg_duration_ms || 0),
        p90DurationMs: Number(item.p90_duration_ms || 0),
      }));

    const kpi = {
      totalCalls: Number(data.kpi?.totalCalls || 0),
      successRate: Number(data.kpi?.successRate || 0),
      avgDurationMs: Number(data.kpi?.avgDurationMs || 0),
      p50DurationMs: Number(data.kpi?.p50DurationMs || 0),
      p90DurationMs: Number(data.kpi?.p90DurationMs || 0),
      activeModelsCount: Number(data.kpi?.activeModelsCount || 0),
    };

    return NextResponse.json(
      {
        range: data.timeRange || timeRange,
        kpi,
        models,
      },
      {
        headers: {
          'Cache-Control': 'public, max-age=15, stale-while-revalidate=45',
        },
      }
    );
  } catch (error) {
    console.error('[public/models/telemetry] failed to load telemetry:', error);
    return NextResponse.json(
      { error: '模型遥测暂不可用' },
      { status: 503, headers: { 'Cache-Control': 'no-store' } }
    );
  }
}

